package com.rohit.inventory.service;
import com.rohit.inventory.dto.request.*; import com.rohit.inventory.dto.response.TransferResponse; import com.rohit.inventory.entity.*; import com.rohit.inventory.exception.*; import com.rohit.inventory.repository.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*; import org.springframework.data.domain.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TransferService { private final StockTransferRepository transfers; private final WarehouseRepository warehouses; private final WarehouseZoneRepository zones; private final ProductRepository products; private final UserRepository users; private final InventoryService inventory; private final AuditService audit; public TransferService(StockTransferRepository transfers,WarehouseRepository warehouses,WarehouseZoneRepository zones,ProductRepository products,UserRepository users,InventoryService inventory,AuditService audit){this.transfers=transfers;this.warehouses=warehouses;this.zones=zones;this.products=products;this.users=users;this.inventory=inventory;this.audit=audit;}
 @Transactional public TransferResponse create(TransferCreateRequest r,String email){User actor=user(email); if(r.sourceWarehouseId().equals(r.destinationWarehouseId()))throw new IllegalArgumentException("Source and destination must differ");Warehouse src=warehouse(r.sourceWarehouseId()),dst=warehouse(r.destinationWarehouseId());active(src);active(dst);scope(actor,src);scope(actor,dst);Set<UUID> seen=new HashSet<>();StockTransfer t=new StockTransfer();t.setTransferNumber("TRF-"+java.time.Year.now()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());t.setStatus(StockTransferStatus.PENDING);t.setSourceWarehouse(src);t.setDestinationWarehouse(dst);t.setRequestedBy(actor);t.setRemarks(r.reason()+((r.notes()==null||r.notes().isBlank())?"":" | "+r.notes()));for(TransferItemRequest x:r.items()){if(!seen.add(x.productId()))throw new IllegalArgumentException("Duplicate product in transfer");Product p=products.findById(x.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found"));if(p.getStatus()!=ProductStatus.ACTIVE)throw new IllegalArgumentException("Product is not active");WarehouseZone sz=zone(x.sourceZoneId(),src),dz=zone(x.destinationZoneId(),dst);StockTransferItem i=new StockTransferItem();i.setProduct(p);i.setSourceZone(sz);i.setDestinationZone(dz);i.setRequestedQuantity(x.quantity());t.addItem(i);}transfers.save(t);audit.record(actor.getId(),"TRANSFER_CREATED","STOCK_TRANSFER",t.getId(),Map.of("transferNumber",t.getTransferNumber()));return out(t);}
 @Transactional(readOnly=true) public Page<TransferResponse> list(StockTransferStatus status,Pageable page){return (status==null?transfers.findAll(page):transfers.findByStatus(status,page)).map(this::out);} @Transactional(readOnly=true) public TransferResponse get(UUID id){return out(find(id));}
 @Transactional public TransferResponse approve(UUID id,String email){StockTransfer t=find(id);transition(t,StockTransferStatus.APPROVED);User a=user(email);scope(a,t.getSourceWarehouse());for(StockTransferItem i:t.getItems()){i.setApprovedQuantity(i.getRequestedQuantity());}t.setApprovedBy(a);t.setApprovedAt(Instant.now());audit.record(a.getId(),"TRANSFER_APPROVED","STOCK_TRANSFER",id,Map.of("status","APPROVED"));return out(t);}
 @Transactional public TransferResponse reject(UUID id,String email,TransferActionRequest req){StockTransfer t=find(id);transition(t,StockTransferStatus.REJECTED);if(req==null||req.notes()==null||req.notes().isBlank())throw new IllegalArgumentException("Rejection reason is required");t.setRemarks(req.notes());audit.record(user(email).getId(),"TRANSFER_REJECTED","STOCK_TRANSFER",id,Map.of("reason",req.notes()));return out(t);}
 @Transactional public TransferResponse pick(UUID id,String email){StockTransfer t=find(id);transition(t,StockTransferStatus.PICKED);scope(user(email),t.getSourceWarehouse());for(StockTransferItem i:t.getItems())i.setPickedQuantity(i.getApprovedQuantity());audit.record(user(email).getId(),"TRANSFER_PICKED","STOCK_TRANSFER",id,Map.of());return out(t);}
 @Transactional public TransferResponse dispatch(UUID id,String email){StockTransfer t=find(id);transition(t,StockTransferStatus.IN_TRANSIT);User a=user(email);scope(a,t.getSourceWarehouse());for(StockTransferItem i:t.getItems()){StockMovementRequest m=new StockMovementRequest(t.getSourceWarehouse().getId(),i.getSourceZone().getId(),i.getProduct().getId(),i.getPickedQuantity(),"TRANSFER_DISPATCH","TRANSFER",id);inventory.stockOut(m,email);i.setDispatchedQuantity(i.getPickedQuantity());}t.setDispatchedAt(Instant.now());audit.record(a.getId(),"TRANSFER_DISPATCHED","STOCK_TRANSFER",id,Map.of());return out(t);}
 @Transactional public TransferResponse receive(UUID id,String email){StockTransfer t=find(id);transition(t,StockTransferStatus.RECEIVED);User a=user(email);scope(a,t.getDestinationWarehouse());for(StockTransferItem i:t.getItems()){StockMovementRequest m=new StockMovementRequest(t.getDestinationWarehouse().getId(),i.getDestinationZone().getId(),i.getProduct().getId(),i.getDispatchedQuantity(),"TRANSFER_RECEIPT","TRANSFER",id);inventory.stockIn(m,email);i.setReceivedQuantity(i.getDispatchedQuantity());}t.setReceivedAt(Instant.now());audit.record(a.getId(),"TRANSFER_RECEIVED","STOCK_TRANSFER",id,Map.of());return out(t);}
 @Transactional public TransferResponse complete(UUID id,String email){StockTransfer t=find(id);transition(t,StockTransferStatus.COMPLETED);if(t.getItems().stream().anyMatch(i->i.getReceivedQuantity().compareTo(i.getDispatchedQuantity())!=0))throw new IllegalArgumentException("All dispatched quantities must be received");t.setCompletedAt(Instant.now());audit.record(user(email).getId(),"TRANSFER_COMPLETED","STOCK_TRANSFER",id,Map.of());return out(t);}
 @Transactional public TransferResponse cancel(UUID id,String email){StockTransfer t=find(id);if(t.getStatus()!=StockTransferStatus.PENDING&&t.getStatus()!=StockTransferStatus.APPROVED)throw new InvalidTransferStateException("Only pending or approved transfers can be cancelled");t.setStatus(StockTransferStatus.CANCELLED);t.setCancellationReason("Cancelled by "+email);audit.record(user(email).getId(),"TRANSFER_CANCELLED","STOCK_TRANSFER",id,Map.of());return out(t);}
 private void transition(StockTransfer t,StockTransferStatus next){Map<StockTransferStatus,Set<StockTransferStatus>> m=Map.of(StockTransferStatus.PENDING,Set.of(StockTransferStatus.APPROVED,StockTransferStatus.REJECTED,StockTransferStatus.CANCELLED),StockTransferStatus.APPROVED,Set.of(StockTransferStatus.PICKED,StockTransferStatus.CANCELLED),StockTransferStatus.PICKED,Set.of(StockTransferStatus.IN_TRANSIT),StockTransferStatus.IN_TRANSIT,Set.of(StockTransferStatus.RECEIVED),StockTransferStatus.RECEIVED,Set.of(StockTransferStatus.COMPLETED));if(!m.getOrDefault(t.getStatus(),Set.of()).contains(next))throw new InvalidTransferStateException("Invalid transfer transition: "+t.getStatus()+" to "+next);t.setStatus(next);}
 private StockTransfer find(UUID id){return transfers.findById(id).orElseThrow(()->new ResourceNotFoundException("Transfer not found"));} private User user(String e){return users.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("User not found"));} private Warehouse warehouse(UUID id){return warehouses.findById(id).orElseThrow(()->new ResourceNotFoundException("Warehouse not found"));} private WarehouseZone zone(UUID id,Warehouse w){WarehouseZone z=zones.findById(id).orElseThrow(()->new ResourceNotFoundException("Warehouse zone not found"));if(!z.getWarehouse().getId().equals(w.getId()))throw new IllegalArgumentException("Zone does not belong to warehouse");return z;} private void active(Warehouse w){if(w.getStatus()!=WarehouseStatus.ACTIVE)throw new IllegalArgumentException("Warehouse is not active");} private void scope(User u,Warehouse w){if(u.getRoles().stream().noneMatch(r->r.getCode().equals("ADMIN")||r.getCode().equals("INVENTORY_MANAGER"))&&u.getAssignedWarehouses().stream().noneMatch(x->x.getId().equals(w.getId())))throw new AccessDeniedException("Warehouse is not assigned to this user");} private TransferResponse out(StockTransfer t){return new TransferResponse(t.getId(),t.getTransferNumber(),t.getStatus().name(),t.getSourceWarehouse().getId(),t.getSourceWarehouse().getName(),t.getDestinationWarehouse().getId(),t.getDestinationWarehouse().getName(),t.getItems().stream().map(i->new TransferResponse.Item(i.getProduct().getId(),i.getProduct().getSku(),i.getProduct().getName(),i.getSourceZone().getId(),i.getDestinationZone().getId(),i.getRequestedQuantity(),i.getApprovedQuantity(),i.getPickedQuantity(),i.getDispatchedQuantity(),i.getReceivedQuantity())).toList(),t.getRemarks(),t.getRemarks(),t.getRequestedAt(),t.getApprovedAt(),t.getDispatchedAt(),t.getReceivedAt(),t.getCompletedAt());}
}
